import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A member of a pool — a person, or another pool (poolId; personId then null) — with their share percent, whether
 *  they are retired by the sheet's today (their share then counts 0.00 toward the pool's total), and their cut of the
 *  pool's pot ('' when the pool is unbalanced or there is no pot). A pool that is a member of none has the sheet's
 *  pot; a member pool's pot is its cut in the pool above. */
export type PoolMember = {
  personId: number | null;
  name: string;
  share: string;
  retired: boolean;
  cut: string;
  poolId: number | null;
};

/** A pool on the sheet: its members in the order they were added, the total of their shares and whether it is
 *  balanced (the total is exactly 100.00). */
export type Pool = { id: number; name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

export const poolsKey = (sheetId: string) => ['sheet', sheetId, 'pools'] as const;

/** The sheet's pools, in the order they were added. */
export function usePools(sheetId: string) {
  return useQuery({
    queryKey: poolsKey(sheetId),
    queryFn: () => getJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`),
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetBody } from '../../slots/defs/sheet';
import { usePeople } from '../people/people';
import { poolsKey, usePools } from './pools';
import type { Pool, PoolMember } from './pools';

/** A share as typed: a percent of at most two decimals, more than 0.00 and at most 100.00. */
function validShare(share: string): boolean {
  if (!/^\d+(\.\d{1,2})?$/.test(share)) return false;
  const n = Number(share);
  return n > 0 && n <= 100;
}

/** A member's key on screen: the person's id, or pool-<name> for a member pool. */
function memberKey(m: PoolMember): string {
  return m.poolId !== null ? `pool-${m.name}` : String(m.personId);
}

/** One pool: its total share, whether balanced, each member's share, and the entry a member (a person, or another
 *  pool chosen as pool:<name>) is added with. */
function PoolRow({ sheetId, user, pool, pools }: { sheetId: string; user: string; pool: Pool; pools: Pool[] }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId).data ?? [];
  // the chosen member: a person's id, or pool:<id>
  const [personId, setPersonId] = useState('');
  const [share, setShare] = useState('');
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const add = useMutation({
    mutationFn: (body: { personId?: number; memberPoolId?: number; share: string }) =>
      postJson(`/api/sheets/${encodeURIComponent(sheetId)}/pools/${pool.id}/members`, { user, ...body }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
      setPersonId('');
      setShare('');
    },
    onError: (e) => setError(e instanceof HttpError && e.body ? e.body : 'Could not add the pool member.'),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (personId === '') {
      setError('Choose the person or pool to add.');
      return;
    }
    const s = share.trim();
    if (!validShare(s)) {
      setError('A share is more than 0.00 and at most 100.00, with at most two decimals.');
      return;
    }
    const memberPoolId = personId.startsWith('pool:') ? Number(personId.slice(5)) : null;
    if (memberPoolId === null && pool.members.some((m) => m.poolId === null && String(m.personId) === personId)) {
      setError('That person is already in the pool.');
      return;
    }
    if (!once.start()) return;
    add.mutate(memberPoolId !== null ? { memberPoolId, share: s } : { personId: Number(personId), share: s });
  };

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <strong>{pool.name}</strong> — total share <span data-testid="pool-total-share">{pool.totalShare}</span>,
      balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li key={memberKey(m)} data-testid={`pool-member-${pool.name}-${memberKey(m)}`}>
            {m.poolId !== null ? `pool ${m.name}` : m.name}: <span data-testid="pool-share">{m.share}</span>, cut <span data-testid="pool-cut">{m.cut}</span>
            {m.retired && ' (retired)'}
          </li>
        ))}
      </ul>
      <form onSubmit={submit}>
        <select
          data-testid="pool-member-select"
          value={personId}
          onChange={(e) => {
            setPersonId(e.target.value);
            setError('');
          }}
        >
          <option value="">Person or pool…</option>
          {people.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
          {pools.map((p) => (
            <option key={`pool:${p.id}`} value={`pool:${p.id}`}>
              {`pool:${p.name}`}
            </option>
          ))}
        </select>{' '}
        <input
          data-testid="pool-member-share"
          placeholder="Share %"
          value={share}
          onChange={(e) => {
            setShare(e.target.value);
            setError('');
          }}
        />{' '}
        <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
          Add member
        </button>
      </form>
      {error && (
        <p data-testid="pool-error" role="alert">
          {error}
        </p>
      )}
    </li>
  );
}

function PoolForm({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
